#include <stdio.h>

void calculate(long long a, long long b, char op, char *out) {
    switch (op) {
        case '+': sprintf(out, "%lld", a + b); break;
        case '-': sprintf(out, "%lld", a - b); break;
        case '*': sprintf(out, "%lld", a * b); break;
        case '/': 
            if (b == 0) sprintf(out, "DIVISION_BY_ZERO");
            else sprintf(out, "%lld", a / b);
            break;
        default: sprintf(out, "INVALID_OPERATOR"); break;
    }
}

