    data = sys.stdin.read().split()
    if not data: return
    n = int(data[0])
    nums = [int(x) for x in data[1:n+1]]
    target = int(data[n+1])
    first = find_bound(nums, target, True)
    last = find_bound(nums, target, False)
    print(f"{first} {last}")

