char paths[500][50];
int pathCount = 0;

int compare(const void *a, const void *b) {
    return strcmp((const char*)a, (const char*)b);
}

void solve(int r, int c, int m[10][10], int n, char path[], int depth, int visited[10][10]) {
    if (r == n - 1 && c == n - 1) {
        path[depth] = '\0';
        strcpy(paths[pathCount++], path);
        return;
    }
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && m[nr][nc] == 1 && !visited[nr][nc]) {
            visited[nr][nc] = 1;
            path[depth] = dChar[i];
            solve(nr, nc, m, n, path, depth + 1, visited);
            visited[nr][nc] = 0;
        }
    }
}

