    char path[50];
    solve(0, 0, m, n, path, 0, visited);
    if (pathCount == 0) {
        printf("-1\n");
    } else {
        qsort(paths, pathCount, sizeof(paths[0]), compare);
        for (int i = 0; i < pathCount; i++) {
            printf("%s\n", paths[i]);
        }
    }
