import java.util.*;

public class Solution {
    private static int[] dr = {1, 0, 0, -1};
    private static int[] dc = {0, -1, 1, 0};
    private static char[] dChar = {'D', 'L', 'R', 'U'};
    private static List<String> paths = new ArrayList<>();

    private static void solve(int r, int c, int[][] m, int n, StringBuilder path, boolean[][] visited) {
        if (r == n - 1 && c == n - 1) {
            paths.add(path.toString());
            return;
        }
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && m[nr][nc] == 1 && !visited[nr][nc]) {
                visited[nr][nc] = true;
                path.append(dChar[i]);
                solve(nr, nc, m, n, path, visited);
                path.deleteCharAt(path.length() - 1);
                visited[nr][nc] = false;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int[][] m = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) m[i][j] = sc.nextInt();
        }
        if (m[0][0] == 0 || m[n - 1][n - 1] == 0) {
            System.out.println("-1");
            return;
        }
        boolean[][] visited = new boolean[n][n];
        visited[0][0] = true;
        solve(0, 0, m, n, new StringBuilder(), visited);
        if (paths.isEmpty()) {
            System.out.println("-1");
        } else {
            Collections.sort(paths);
            for (String p : paths) System.out.println(p);
        }
    }
}

