#include <stdio.h>
#include <limits.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

int main() {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return 0;
    int A[100005], B[100005];
    for (int i = 0; i < m; i++) scanf("%d", &A[i]);
    for (int i = 0; i < n; i++) scanf("%d", &B[i]);

    int *pA = A, *pB = B;
    if (m > n) {
        pA = B; pB = A;
        int t = m; m = n; n = t;
    }

    int low = 0, high = m;
    int halfLen = (m + n + 1) / 2;
    double median = 0.0;

    while (low <= high) {
        int i = low + (high - low) / 2;
        int j = halfLen - i;

        int maxLeftA = (i == 0) ? INT_MIN : pA[i - 1];
        int minRightA = (i == m) ? INT_MAX : pA[i];
        int maxLeftB = (j == 0) ? INT_MIN : pB[j - 1];
        int minRightB = (j == n) ? INT_MAX : pB[j];

        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            if ((m + n) % 2 == 1) {
                median = (double)MAX(maxLeftA, maxLeftB);
            } else {
                median = (MAX(maxLeftA, maxLeftB) + MIN(minRightA, minRightB)) / 2.0;
            }
            break;
        } else if (maxLeftA > minRightB) {
            high = i - 1;
        } else {
            low = i + 1;
        }
    }
    printf("%.5f\n", median);
    return 0;
}

