int totalSolutions = 0;

void solve(int row, int n, int cols, int d1, int d2) {
    if (row == n) {
        totalSolutions++;
        return;
    }
    int available = ((1 << n) - 1) & ~(cols | d1 | d2);
    while (available) {
        int p = available & -available;
        available -= p;
        solve(row + 1, n, cols | p, (d1 | p) << 1, (d2 | p) >> 1);
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    solve(0, n, 0, 0, 0);
    printf("%d\n", totalSolutions);
    return 0;
}

