void getLargestAndSecond(const int arr[], int n, int* largest, int* second) {
    *largest = INT_MIN;
    *second = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (arr[i] > *largest) {
            *second = *largest;
            *largest = arr[i];
        } else if (arr[i] < *largest && arr[i] > *second) {
            *second = arr[i];
        }
    }
    if (*second == INT_MIN) *second = -1;
}

