int leaders(const int arr[], int n, int res[]) {
    int maxFromRight = INT_MIN;
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (arr[i] > maxFromRight) {
            res[count++] = arr[i];
            maxFromRight = arr[i];
        }
    }
    for (int i = 0; i < count / 2; i++) {
        int t = res[i]; res[i] = res[count - 1 - i]; res[count - 1 - i] = t;
    }
    return count;
}

