#include <stdlib.h>
int cmp(const void* a, const void* b) { return (*(int*)a > *(int*)b) - (*(int*)a < *(int*)b); }
int longestConsecutive(int nums[], int n) {
    if (n == 0) return 0;
    qsort(nums, n, sizeof(int), cmp);
    int maxLen = 1, curLen = 1;
    for (int i = 1; i < n; i++) {
        if (nums[i] == nums[i - 1]) continue;
        if (nums[i] == nums[i - 1] + 1) curLen++;
        else { if (curLen > maxLen) maxLen = curLen; curLen = 1; }
    }
    return curLen > maxLen ? curLen : maxLen;
}

