int maxProduct(const int nums[], int n) {
    int maxProd = nums[0], minProd = nums[0], result = nums[0];
    for (int i = 1; i < n; i++) {
        int x = nums[i];
        if (x < 0) { int t = maxProd; maxProd = minProd; minProd = t; }
        maxProd = MAX(x, maxProd * x);
        minProd = MIN(x, minProd * x);
        result = MAX(result, maxProd);
    }
    return result;
}

