int main() {
    char s[100005], t[100005];
    if (scanf("%s %s", s, t) != 2) return 0;
    int target[128] = {0}, window[128] = {0};
    for (int i = 0; t[i] != '\0'; i++) target[(unsigned char)t[i]]++;
    int required = 0;
    for (int i = 0; i < 128; i++) if (target[i] > 0) required++;

    int left = 0, formed = 0;
    int minLen = INT_MAX, startIdx = -1;
    int n = strlen(s);
    for (int right = 0; right < n; right++) {
        unsigned char c = (unsigned char)s[right];
        window[c]++;
        if (target[c] > 0 && window[c] == target[c]) formed++;

        while (left <= right && formed == required) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                startIdx = left;
            }
            unsigned char lc = (unsigned char)s[left];
            window[lc]--;
            if (target[lc] > 0 && window[lc] < target[lc]) formed--;
            left++;
        }
    }
    if (startIdx == -1) {
        printf("-1\n");
    } else {
        for (int i = 0; i < minLen; i++) putchar(s[startIdx + i]);
        putchar('\n');
    }
    return 0;
}

