#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a; *a = *b; *b = t;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int mat[105][105];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) scanf("%d", &mat[i][j]);
    }
    // Transpose
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            swap(&mat[i][j], &mat[j][i]);
        }
    }
    // Reverse rows
    for (int i = 0; i < n; i++) {
        int l = 0, r = n - 1;
        while (l < r) {
            swap(&mat[i][l], &mat[i][r]);
            l++; r--;
        }
        for (int j = 0; j < n; j++) {
            printf("%d%s", mat[i][j], (j == n - 1) ? "" : " ");
        }
        printf("\n");
    }
    return 0;
}

